INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (195, 403, 'BOPP Metallized film aluminium silver', '../upload/image/20211215/20211215203711_18066.jpg', '<p><span class="nownavi" style="font-family:Tahoma;"><strong><span class="nownavi"><span style="font-size:18px;color:#009900;">BOPP Metallized film aluminium silver</span><br/> </span></strong></span></p> <div style="font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> <strong><span style="font-size:18px;color:#009900;font-family:Tahoma;">BOPP (</span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;">Polypropylene)</span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;">aluminum&nbsp;</span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;">metallized film (silver)</span> </strong> </div> <div style="font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> <strong><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Thickness : 15,18,20,25,30,35 Microns</strong></span><br/> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Width : 350-1500MM</strong></span><br/> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Length :5000-12000M</strong></span><strong>&nbsp;</strong><br/> <div> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Color : silver&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>aluminum&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>metallized</strong></span> </div> <div> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Package : Standard exporting package with pallets .</strong></span><br/> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Application : lamination &amp; printing and so forth.</strong></span> </div> <div> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Usgae: food packing or others packing.</strong></span> </div> </strong> </div> <div style="font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> <strong><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Future:&nbsp; inner side corona treatment and&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>aluminum&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>metallized, outer&nbsp;</strong></span><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>side heat sealable, ( basic BOPP is two sides heat sealable BOPP）</strong></span> </strong> </div> <strong> <p></p> <div style="font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>or&nbsp;</strong></span><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>outer side corona treatment and&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>aluminum&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>metallized, and inner&nbsp;</strong></span><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>side heat sealable, ( basic BOPP is two sides heat sealable BOPP）</strong></span> </div> </strong> <p><br/></p> <div style="color:#000000;font-family:Calibri;font-size:19px;font-style:normal;font-weight:400;text-align:start;background-color:#FFFFFF;"> <br/> </div> <br/> <p><br/></p> <p><span class="nownavi"><br/> </span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (195, 425, 'Metalized BOPP film heat sealable one side and treated the other side', '../upload/image/no-photo.png', '<p><span style="font-size:18px;font-family:Tahoma;color:#009900;">Metalized BOPP film heat sealable one side and treated the other side.&nbsp;</span></p> <p><span style="font-size:18px;font-family:Tahoma;color:#009900;">[Metalized BOPP film heat sealable one side and treated the other side.]</span></p> <br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">1// Product Description</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">Metalized BOPP film heat sealable one side and treated the other side.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">2// General Use</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">It is used in laminations with other films for packaging of foodstuffs such as crackers, chips and other "snacks", requiring a good seal and large rate of sealing.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">3// Properties and Tolerance</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">4// Packing</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">The standard armed pallet will have a polyester band, triple tensioned wrapping, floor and roof covered with PE or CPP and one wood plank will join another like an "H".</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">The pallet will be composed of 2 to 6 reels of equal width and thickness. The caps should be plywood preferably triple and must be of 25mm thickness.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">The reels should have up to 2 connections per roll and shall not exceed 10% of the total batch.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">5// Warranty.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">The supplier shall certify that the film will maintain its physical and chemical properties for a minimum period of 6 months from the date of production, for each lot a certificate of quality containing the physical and/or chemical analysis will be sent.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">The supplier shall ensure that the film can be used in direct contact with food and that meets the requirements in accordance with the regulations of the EEC 90/128 and the FDA# 21 CFR 177.1720</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">6// Identification</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">Each reel must have an external label with the following information:</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">//Supplier Name.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">//Type of Film.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">//Purchase Order ·</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">//Code of the material.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">//Date of manufacture.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">//Due Date.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">//Meters, width and thickness</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">//Gross Weight and net weight.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">//Internal or external Treated Layer</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">//Number of connections</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">7//Storage and Handling</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">It is not recommended submitting the film to conditions of high humidity and extreme temperatures, it is recommended to avoid any moisture condensation on the film, and that will not exceed an ambient temperature of 35º C and a relative humidity of 60 %, it is recommended to protect the reels from direct exposure to sunlight or heat sources.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">The pallet must be transported and protected with a plastic cover until its use; the palletizing must be made with dry wood to ensure no moisture release in the transportation.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">8// Foreign bodies</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">The film should have no strange smell and should be free from foreign bodies.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">9// Microbiology</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">The film will not show a count greater than 100 cfu/g of aerobic mesophile and must be completely free of bacteria.</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">10//Toxicological information</span><br/> <span style="font-size:18px;font-family:Tahoma;color:#009900;">The film does not have specific danger when it is used in an appropriate manner and is not associated with any toxic compound, there are no known carcinogenic effects of these compounds, are not used substances that can cause damage to health, it is a flammable product, but may burn when it is exposed to the flame by releasing a smoke harmful to health, preventing breathing.</span><br/> <p><span style="font-size:18px;font-family:Tahoma;color:#009900;">SIGMAPLAST reserves the right to refuse a lot or disqualify a supplier by not complying with the tolerances exposed.</span></p> <p><span style="font-size:18px;font-family:Tahoma;color:#009900;"><br/> </span></p> <p><span style="font-size:18px;font-family:Tahoma;color:#009900;"><br/> </span></p>', '2026-09-06 20:58:45');